package com.siestech.booksharing.Practical;
import android.Manifest; import android.content.Intent; import android.content.pm.PackageManager; import android.location.Location; import android.location.LocationListener; import android.location.LocationManager; import android.net.Uri; import android.os.Bundle; import android.provider.Settings; import android.widget.TextView; import android.widget.Toast; import androidx.annotation.NonNull; import androidx.appcompat.app.AppCompatActivity; import androidx.core.app.ActivityCompat; import com.siestech.booksharing.R;
public class LocationActivity extends AppCompatActivity{private LocationManager manager;private TextView out;private double lat,lon;private static final int LOC=93;private final LocationListener listener=new LocationListener(){@Override public void onLocationChanged(@NonNull Location l){lat=l.getLatitude();lon=l.getLongitude();out.setText("Latitude: "+lat+"\nLongitude: "+lon+"\nAccuracy: "+l.getAccuracy()+" m");}};@Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_location);out=findViewById(R.id.locationText);manager=(LocationManager)getSystemService(LOCATION_SERVICE);findViewById(R.id.getLocationBtn).setOnClickListener(v->getLocation());findViewById(R.id.openMapBtn).setOnClickListener(v->{if(lat==0&&lon==0){Toast.makeText(this,"Get your location first",Toast.LENGTH_SHORT).show();return;}startActivity(new Intent(Intent.ACTION_VIEW, Uri.parse("geo:"+lat+","+lon+"?q="+lat+","+lon)));});}private void getLocation(){if(ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACCESS_COARSE_LOCATION)!=PackageManager.PERMISSION_GRANTED){ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);return;}try{boolean gps=manager.isProviderEnabled(LocationManager.GPS_PROVIDER);if(!gps)startActivity(new Intent(Settings.ACTION_LOCATION_SOURCE_SETTINGS));manager.requestLocationUpdates(LocationManager.GPS_PROVIDER,1000,1,listener);Location last=manager.getLastKnownLocation(LocationManager.GPS_PROVIDER);if(last!=null)listener.onLocationChanged(last);}catch(Exception e){Toast.makeText(this,"Unable to read location",Toast.LENGTH_LONG).show();}}@Override public void onRequestPermissionsResult(int r,@NonNull String[] p,@NonNull int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC)getLocation();}@Override protected void onDestroy(){try{manager.removeUpdates(listener);}catch(Exception ignored){}super.onDestroy();}}
